package dev.alex.fyt.probe;
import android.app.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.text.*;import android.view.*;import android.widget.*;
/** Compact accent presets and an HSV selector with editable RGB channels. */
public final class AccentController {
 private final Activity activity;private final Runnable changed;
 public AccentController(Activity a,Runnable changed){activity=a;this.changed=changed;}
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private TextView label(String s,int colour){TextView v=new TextView(activity);v.setText(s);v.setTextColor(colour);v.setTextSize(12);return v;}
 public View controls(){ThemeSettings.Palette p=ThemeSettings.resolve(activity).palette;LinearLayout box=new LinearLayout(activity);box.setOrientation(1);TextView heading=label(I18n.t(R.string.accent_title),p.muted);heading.setPadding(0,dp(12),0,dp(6));box.addView(heading);
  LinearLayout options=new LinearLayout(activity);int[] names={R.string.accent_blue,R.string.accent_electric,R.string.accent_red,R.string.accent_teal,R.string.accent_green,R.string.accent_amber,R.string.accent_indigo};int selected=ThemeSettings.accent(activity);
  for(int i=0;i<AccentColors.PRESETS.length;i++){final int colour=AccentColors.PRESETS[i];Button b=ConsoleControls.button(activity,I18n.t(names[i]),p,selected==colour);GradientDrawable swatch=new GradientDrawable();swatch.setShape(GradientDrawable.OVAL);swatch.setColor(AccentColors.tone(colour,p.night));swatch.setStroke(dp(1),p.border);swatch.setBounds(0,0,dp(16),dp(16));b.setCompoundDrawablesRelative(swatch,null,null,null);b.setCompoundDrawablePadding(dp(6));b.setContentDescription(I18n.t(names[i])+String.format(java.util.Locale.US," · #%06X",colour&0xFFFFFF));b.setOnClickListener(v->{ThemeSettings.accent(activity,colour);changed.run();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(48));lp.rightMargin=dp(8);options.addView(b,lp);}
  boolean custom=true;for(int c:AccentColors.PRESETS)if(c==selected)custom=false;Button choose=ConsoleControls.button(activity,I18n.t(R.string.accent_custom),p,custom);choose.setOnClickListener(v->showPicker());options.addView(choose,new LinearLayout.LayoutParams(-2,dp(48)));HorizontalScrollView scroll=new HorizontalScrollView(activity);scroll.setHorizontalScrollBarEnabled(false);scroll.addView(options);box.addView(scroll);TextView notes=label(I18n.t(R.string.accent_notes),p.muted);notes.setPadding(0,dp(6),0,0);box.addView(notes);return box;
 }
 private void showPicker(){ThemeSettings.Palette p=ThemeSettings.resolve(activity).palette;LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(dp(20),dp(8),dp(20),dp(8));
  final int[] selected={ThemeSettings.accent(activity)};final boolean[] syncing={false};TextView preview=label("",AccentColors.foreground(selected[0]));preview.setGravity(Gravity.CENTER);preview.setPadding(0,dp(8),0,dp(8));box.addView(preview,new LinearLayout.LayoutParams(-1,dp(32)));
  Field picker=new Field(selected[0]);box.addView(picker,new LinearLayout.LayoutParams(-1,dp(100)));SeekBar hue=new SeekBar(activity);hue.setMax(359);hue.setContentDescription(I18n.t(R.string.accent_hue));box.addView(label(I18n.t(R.string.accent_hue),p.muted));box.addView(hue,new LinearLayout.LayoutParams(-1,dp(32)));
  EditText[] rgb=new EditText[3];LinearLayout channels=new LinearLayout(activity);String[] labels={"R","G","B"};for(int i=0;i<3;i++){LinearLayout channel=new LinearLayout(activity);channel.setOrientation(1);channel.addView(label(labels[i],p.muted));EditText input=new EditText(activity);rgb[i]=input;input.setSingleLine(true);input.setTextSize(16);input.setTextColor(p.text);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(3)});input.setContentDescription(labels[i]+" 0–255");channel.addView(input);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(84),-2);lp.rightMargin=dp(12);channels.addView(channel,lp);}box.addView(channels);
  Runnable refresh=()->{syncing[0]=true;int colour=selected[0];preview.setText(String.format(java.util.Locale.US,"#%06X",colour&0xFFFFFF));preview.setBackgroundColor(colour);preview.setTextColor(AccentColors.foreground(colour));for(int i=0;i<3;i++){rgb[i].setText(String.valueOf((colour>>(16-i*8))&255));rgb[i].setError(null);}picker.invalidate();hue.setProgress(Math.round(picker.hsv[0])%360);syncing[0]=false;};
  picker.changed=colour->{selected[0]=colour;refresh.run();};hue.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(!user||syncing[0])return;picker.hsv[0]=value;selected[0]=Color.HSVToColor(picker.hsv);refresh.run();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
  TextWatcher edits=new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){}public void afterTextChanged(Editable e){if(syncing[0])return;int value=readRgb(rgb,false);if(value==0)return;selected[0]=value;picker.colour(value);syncing[0]=true;hue.setProgress(Math.round(picker.hsv[0])%360);syncing[0]=false;preview.setText(String.format(java.util.Locale.US,"#%06X",value&0xFFFFFF));preview.setBackgroundColor(value);preview.setTextColor(AccentColors.foreground(value));}};for(EditText input:rgb)input.addTextChangedListener(edits);refresh.run();
  ScrollView content=new ScrollView(activity);content.addView(box);AlertDialog dialog=new AlertDialog.Builder(activity,p.night?AlertDialog.THEME_DEVICE_DEFAULT_DARK:AlertDialog.THEME_DEVICE_DEFAULT_LIGHT).setTitle(I18n.t(R.string.accent_custom)).setView(content).setPositiveButton(I18n.t(R.string.ui_save),null).setNegativeButton(I18n.t(R.string.ui_cancel),null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{int colour=readRgb(rgb,true);if(colour==0)return;ThemeSettings.accent(activity,colour);dialog.dismiss();changed.run();}));dialog.show();
 }
 private int readRgb(EditText[] fields,boolean errors){int colour=0xFF000000;boolean valid=true;for(int i=0;i<3;i++){try{int n=Integer.parseInt(fields[i].getText().toString());if(n<0||n>255)throw new NumberFormatException();colour|=n<<(16-i*8);fields[i].setError(null);}catch(NumberFormatException e){valid=false;if(errors)fields[i].setError(I18n.t(R.string.accent_rgb_error));}}return valid?colour:0;}
 private interface Change{void accept(int colour);}
 private final class Field extends View {
  final float[] hsv=new float[3];private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);Change changed;
  Field(int c){super(activity);colour(c);setContentDescription(I18n.t(R.string.accent_selector));}
  void colour(int colour){float previousHue=hsv[0];Color.colorToHSV(colour,hsv);if(hsv[1]==0||hsv[2]==0)hsv[0]=previousHue;invalidate();}
  @Override protected void onDraw(Canvas c){float left=dp(8),top=dp(8),right=getWidth()-dp(8),bottom=getHeight()-dp(8);paint.setShader(new LinearGradient(left,0,right,0,Color.WHITE,Color.HSVToColor(new float[]{hsv[0],1,1}),Shader.TileMode.CLAMP));c.drawRect(left,top,right,bottom,paint);paint.setShader(new LinearGradient(0,top,0,bottom,Color.TRANSPARENT,Color.BLACK,Shader.TileMode.CLAMP));c.drawRect(left,top,right,bottom,paint);paint.setShader(null);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(2));float x=left+(right-left)*hsv[1],y=top+(bottom-top)*(1-hsv[2]);paint.setColor(Color.BLACK);c.drawCircle(x,y,dp(7),paint);paint.setColor(Color.WHITE);c.drawCircle(x,y,dp(5),paint);paint.setStyle(Paint.Style.FILL);}
  @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN||e.getActionMasked()==MotionEvent.ACTION_MOVE){getParent().requestDisallowInterceptTouchEvent(true);hsv[1]=Math.max(0,Math.min(1,(e.getX()-dp(8))/Math.max(1,getWidth()-dp(16))));hsv[2]=1-Math.max(0,Math.min(1,(e.getY()-dp(8))/Math.max(1,getHeight()-dp(16))));invalidate();if(changed!=null)changed.accept(Color.HSVToColor(hsv));return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){getParent().requestDisallowInterceptTouchEvent(false);performClick();return true;}return e.getActionMasked()==MotionEvent.ACTION_CANCEL;}
  @Override public boolean performClick(){super.performClick();return true;}
 }
}
